window.docContents[94].resolve({"/releases/#release-v4___34___0":{"contents":"\n\n* Breaking change: All colors in rendered Lean code are now controlled by CSS variables, and the message text color variables have new names. (#954)* Added Errata, a testing framework with test discovery, uniform failure reporting, and CI-friendly report formats. (#956, #957)* Each change to Verso now describes itself in its own release note entry, and the version sections of this chapter are computed from the Lean toolchain. (#950)\n\n\n\n\n\n\n\n","context":"Writing Documentation in Lean with Verso\u0009Release Notes","header":"Verso 4.34.0","id":"/releases/#release-v4___34___0"}});